const fs = require('fs');

// Promise wrapper
const readFileAsync = (path) => {
  return new Promise((resolve, reject) => {
    fs.readFile(path, 'utf8', (err, data) => {
      if (err) reject(err);
      else resolve(data);
    });
  });
};

// Chaining
readFileAsync('config.json')
  .then(JSON.parse)
  .then(config => console.log('Port:', config.port))
  .catch(err => console.error('Error:', err.message));
```

