class TypedEventEmitter {
  constructor() {
    this.listeners = new Map();
    this.maxListeners = 10;
  }

  on(event, fn) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const list = this.listeners.get(event);
    if (list.length >= this.maxListeners) {
      console.warn(`Max listeners (${this.maxListeners}) exceeded for event: ${event}`);
    }
    list.push(fn);
    return this;
  }

  emit(event, ...args) {
    const list = this.listeners.get(event) || [];
    const wildcards = this.listeners.get('*') || [];
    [...list, ...wildcards].forEach(fn => fn(event, ...args));
    return list.length + wildcards.length > 0;
  }

  once(event, fn) {
    const wrapper = (e, ...args) => {
      fn(e, ...args);
      this.off(event, wrapper);
    };
    return this.on(event, wrapper);
  }

  off(event, fn) {
    const list = this.listeners.get(event);
    if (list) {
      this.listeners.set(event, list.filter(l => l !== fn));
    }
    return this;
  }
}
